   143  int h2o_http2_decode_data_payload(h2o_http2_data_payload_t *payload, const h2o_http2_frame_t *frame, const char **err_desc)
   144  {
   145      if (frame->stream_id == 0) {
   146          *err_desc = "invalid stream id in DATA frame";
   147          return H2O_HTTP2_ERROR_PROTOCOL;
   148      }
   149
   150      if ((frame->flags & H2O_HTTP2_FRAME_FLAG_PADDED) != 0) {
   151          uint8_t padding_length;
   152          if (frame->length < 1) {
   153              *err_desc = "invalid DATA frame";
   154              return H2O_HTTP2_ERROR_PROTOCOL;
   155          }
   156          padding_length = frame->payload[0];
   157          if (frame->length < 1 + padding_length) {
   158              *err_desc = "invalid DATA frame";
   159              return H2O_HTTP2_ERROR_PROTOCOL;
   160          }
   161          payload->data = frame->payload + 1;
   162          payload->length = frame->length - (1 + padding_length);
   163      } else {
   164          payload->data = frame->payload;
   165          payload->length = frame->length;
   166      }
   167      return 0;
   168  }
