   180  int h2o_http2_decode_headers_payload(h2o_http2_headers_payload_t *payload, const h2o_http2_frame_t *frame, const char **err_desc)
   181  {
   182      const uint8_t *src = frame->payload, *src_end = frame->payload + frame->length;
   183
   184      if (frame->stream_id == 0) {
   185          *err_desc = "invalid stream id in HEADERS frame";
   186          return H2O_HTTP2_ERROR_PROTOCOL;
   187      }
   188
   189      if ((frame->flags & H2O_HTTP2_FRAME_FLAG_PADDED) != 0) {
   190          uint32_t padlen;
   191          if (src == src_end) {
   192              *err_desc = "invalid HEADERS frame";
   193              return H2O_HTTP2_ERROR_PROTOCOL;
   194          }
   195          padlen = *src++;
   196          if (src_end - src < padlen) {
   197              *err_desc = "invalid HEADERS frame";
   198              return H2O_HTTP2_ERROR_PROTOCOL;
   199          }
   200          src_end -= padlen;
   201      }
   202
   203      if ((frame->flags & H2O_HTTP2_FRAME_FLAG_PRIORITY) != 0) {
   204          if (src_end - src < 5)
   205              return -1;
   206          src = decode_priority(&payload->priority, src);
   207      } else {
   208          payload->priority = h2o_http2_default_priority;
   209      }
